test "review probe: a callback can cancel its own context" {
    const Fake = struct {
        fn measure(_: *anyopaque, _: *Node, out_width: f32, out: *[2]f32) void { _ = out_width; out.* = .{ 0, 0 }; }
        fn laid(_: *anyopaque) void {}
        fn removed(_: *anyopaque, _: *Node) void {}
        fn timer(_: *anyopaque, _: *Engine, _: u32, _: u32) void {}
        fn invoke(_: *anyopaque, _: *Engine, _: u32, _: []const u8, _: []const u8) void {}
        fn focus(_: *anyopaque, _: *Node) void {}
        fn boot(_: *Engine) !void {}
        fn cancel(ctx: *anyopaque, e: *Engine, _: f64) bool { e.removeFrameHooks(ctx); return false; }
    };
    const saved = configured_driver;
    defer configured_driver = saved;
    configured_driver = .{ .boot = Fake.boot };
    var ctx: u8 = 0;
    const e = try Engine.create(std.testing.allocator, .{ .ctx = &ctx, .measure = Fake.measure, .laid_out = Fake.laid, .removed = Fake.removed, .add_timer = Fake.timer, .invoke = Fake.invoke, .focus = Fake.focus }, &.{}, "{}", "main", "bench.oriel", 900, 700);
    defer e.destroy();
    try e.addFrameHook(.{ .ctx = &ctx, .func = Fake.cancel });
    e.displayFrame(16.67);
    try std.testing.expectEqual(@as(usize, 0), e.frame_hooks.items.len);
}
